  .sub b { background: var(--red); color: var(--white); padding: 0 0.3em; }
  .scroll-cue { margin-top: 2rem; font-size: 0.85rem; font-weight: 600; }
  .scroll-cue a { color: var(--blue); text-decoration-thickness: 3px; }

